import {
  CandleInterval,
  QuantitativeSignal,
  QuantitativeStrategyType,
  SignalType,
} from '@tradegrid/shared-types';
import { StrategyRegistry } from './strategies';
import { HistoricalDataService, historicalDataService as defaultHistoricalDataService } from './historical-data.service';
import { IInstrumentRepository, instrumentRepository as defaultInstrumentRepo } from '../market/instrument.repository';

const SIGNAL_DISCLAIMER =
  'EDUCATIONAL RESEARCH SIGNAL — Generated by rule-based quantitative models. Not financial advice, trading recommendation, or guaranteed prediction. Does not execute orders.';

export class SignalsService {
  constructor(
    private readonly historicalData: HistoricalDataService = defaultHistoricalDataService,
    private readonly instrumentRepo: IInstrumentRepository = defaultInstrumentRepo
  ) {}

  /**
   * Scans active market instruments and produces real-time rule-based signals.
   */
  async generateSignals(options?: {
    symbol?: string;
    strategyType?: QuantitativeStrategyType;
    signalType?: SignalType;
    interval?: CandleInterval;
    limit?: number;
  }): Promise<QuantitativeSignal[]> {
    const {
      symbol,
      strategyType,
      signalType,
      interval = '1d',
      limit = 20,
    } = options || {};

    // 1. Identify target instruments
    const instResult: any = await this.instrumentRepo.findAll();
    let instruments = Array.isArray(instResult) ? instResult : instResult.instruments || [];
    if (symbol) {
      instruments = instruments.filter(
        (i: any) => i.symbol.toUpperCase() === symbol.toUpperCase()
      );
    } else {
      // Pick top active instruments for scanning
      instruments = instruments.slice(0, 8);
    }

    // 2. Identify target strategies
    const strategies = strategyType
      ? [StrategyRegistry.getStrategy(strategyType)]
      : StrategyRegistry.getAllStrategies();

    const signals: QuantitativeSignal[] = [];
    let signalIdCounter = 1;

    for (const inst of instruments) {
      try {
        const dataset = await this.historicalData.getHistoricalCandles({
          symbol: inst.symbol,
          interval,
          limit: 100,
        });

        if (dataset.candles.length < 5) continue;

        const currentPrice = parseFloat(dataset.candles[dataset.candles.length - 1].close);
        const timestamp = dataset.candles[dataset.candles.length - 1].timestamp;

        for (const strat of strategies) {
          const evalResult = strat.evaluateLatest(dataset.candles);

          // Filter by signal type if requested
          if (signalType && evalResult.signal !== signalType) {
            continue;
          }

          signals.push({
            id: signalIdCounter++,
            instrumentId: inst.id,
            symbol: inst.symbol,
            name: inst.name,
            strategyType: strat.type,
            signalType: evalResult.signal,
            strength: evalResult.strength,
            score: evalResult.score,
            currentPrice: Number(currentPrice.toFixed(4)),
            indicatorValues: evalResult.indicatorValues,
            explanation: evalResult.explanation,
            timestamp,
            disclaimer: SIGNAL_DISCLAIMER,
          });

          if (signals.length >= limit) break;
        }
      } catch {
        // Skip unquoteable instruments gracefully
        continue;
      }

      if (signals.length >= limit) break;
    }

    // Sort: actionable signals (BUY/SELL) first, then strongest score magnitude
    signals.sort((a, b) => {
      const aAction = a.signalType !== 'HOLD' ? 1 : 0;
      const bAction = b.signalType !== 'HOLD' ? 1 : 0;
      if (bAction !== aAction) return bAction - aAction;
      return Math.abs(b.score) - Math.abs(a.score);
    });

    return signals.slice(0, limit);
  }
}

export const signalsService = new SignalsService();
